/* Official brand colors; a few lightened (C++, pandas, NumPy) or
   inverted (Flask is black) so every logo stays readable on the
   dark theme. */
const COLORS = {
  python: "#3776AB",
  cplusplus: "#659AD2",
  typescript: "#3178C6",
  pytorch: "#EE4C2C",
  tensorflow: "#FF6F00",
  scikitlearn: "#F7931E",
  huggingface: "#FFD21E",
  opencv: "#5C3EE8",
  apachespark: "#E25A1C",
  apacheairflow: "#017CEE",
  apachehadoop: "#66CCFF",
  pandas: "#E70488",
  numpy: "#4DABCF",
  postgresql: "#4169E1",
  mysql: "#4479A1",
  clickhouse: "#FFCC01",
  fastapi: "#009688",
  flask: "#E8ECF8",
  react: "#61DAFB",
  docker: "#2496ED",
  git: "#F05032",
};

export const hasBrandIcon = (key) => Boolean(PATHS[key]);

/* Returns a colored inline SVG for a known brand, or "" otherwise */
export const brandIcon = (key, size = 20) =>
  PATHS[key]
    ? `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="${COLORS[key] || "currentColor"}" aria-hidden="true"><path d="${PATHS[key]}"/></svg>`
    : "";
